-- Estrutura das tabelas da 2.0 (banco crm-rota), copiada em 10/11/2026.
-- Usar SOMENTE no banco de testes, para ele ficar igual ao real. No banco real essas tabelas já existem.
create sequence if not exists public.products_id_seq;

create table if not exists public.clients ( id uuid default gen_random_uuid() not null, name text not null, route text not null, inactive boolean default false, created_at timestamp with time zone default now(), erp_code text, ordem integer default 0, empresa_id text default 'mageski'::text, rotas text[] default '{}'::text[], UNIQUE (erp_code), PRIMARY KEY (id) );
create table if not exists public.daily_goals ( id uuid default gen_random_uuid() not null, user_id uuid not null, route text not null, goal_value numeric not null, date date default CURRENT_DATE, created_at timestamp with time zone default now(), dt_entrega date, PRIMARY KEY (id), UNIQUE (user_id, route, date) );
create table if not exists public.entregas ( id uuid default gen_random_uuid() not null, user_id uuid not null, client_id uuid, client_name text not null, route text, observacao text not null, date date default CURRENT_DATE not null, delivery_time text, gps_lat double precision, gps_lng double precision, created_at timestamp with time zone default now(), PRIMARY KEY (id) );
create table if not exists public.orders ( id uuid default gen_random_uuid() not null, user_id uuid not null, client_id uuid, client_name text not null, client_erp_code text, route text, situacao text default 'Pedido S/ NFe'::text, forma_pgto integer, produtos jsonb default '[]'::jsonb not null, total numeric default 0, status text default 'pendente'::text, date date default CURRENT_DATE, created_at timestamp with time zone default now(), vencimento date default CURRENT_DATE, gps_lat double precision, gps_lng double precision, PRIMARY KEY (id) );
create table if not exists public.products ( id integer default nextval('products_id_seq'::regclass) not null, erp_code integer, descricao text, codigo_proprio text, preco_venda numeric, unidade text, updated_at timestamp with time zone default now(), tags text[], UNIQUE (erp_code), PRIMARY KEY (id) );
create table if not exists public.sales ( id uuid default gen_random_uuid() not null, user_id uuid not null, client_id uuid, client_name text not null, route text not null, value numeric not null, note text, sale_time text, date date default CURRENT_DATE, created_at timestamp with time zone default now(), erp_code integer, gps_lat double precision, gps_lng double precision, PRIMARY KEY (id) );
create table if not exists public.sales_items ( id uuid default gen_random_uuid() not null, sale_id uuid, user_id uuid, client_erp_code text, erp_code integer, descricao text, codigo_proprio text, quant numeric, preco numeric, vdesc numeric default 0, total numeric, date date default CURRENT_DATE, created_at timestamp with time zone default now(), PRIMARY KEY (id) );
create table if not exists public.user_config ( user_id uuid not null, egestor_vendedor_code integer, name text, rotas text[] default '{}'::text[], perfil text default 'vendedor'::text, PRIMARY KEY (user_id) );
create table if not exists public.visitas_sem_venda ( id uuid default gen_random_uuid() not null, user_id uuid not null, client_id uuid, client_name text not null, route text, motivo text not null, observacao text, date date default CURRENT_DATE not null, visit_time text, gps_lat double precision, gps_lng double precision, created_at timestamp with time zone default now(), PRIMARY KEY (id) );
create table if not exists public.webhook_config ( key text not null, value text, PRIMARY KEY (key) );
alter sequence public.products_id_seq owned by public.products.id;
